INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (1, 1, N'preamble', N'Introduction', N'Toyota Kirloskar Motor Pvt. Ltd. engaged Bureau Veritas to carry out an Electrical Safety Assessment of Sunny Toyota, Agra (AG02A), 632, Artoni, Agra Mathura Road, Agra, Uttar Pradesh, 282007. The visit was on 23 December 2025. Findings are based on document review, inspection of electrical installations and discussions with dealership personnel. Recommendations apply to the conditions seen at this location.');
INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (2, 1, N'objectives', N'Objectives', N'Identify hazards in the operation and maintenance of electrical equipment. Review procedures, statutory compliance and opportunities to improve electrical safety performance.');
INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (3, 1, N'scope', N'Scope', N'Visual inspection and document review of electrical installations, PPE, earthing checks, training, maintenance and LOTO records, incident records and change management. Thermography, load balance at the main incomer and neutral-to-earth voltage were in scope. Other performance tests were not.');
INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (4, 1, N'strengths', N'Key strengths and good safety practices', N'Earth pit identification is completed with clear markings.
INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (5, 1, N'opportunities', N'Additional opportunities', N'Provide a gland plate on the PDB and standard cable glands.
INSERT INTO dbo.assessment_narratives ([id], [assessment_id], [code], [title], [body]) VALUES (6, 1, N'disclaimer', N'Disclaimer', N'This report records the electrical safety assessment of the named dealership. It is issued within the contract with Toyota Kirloskar Motor Pvt. Ltd. and does not by itself determine statutory compliance or legal liability.');
